content.text:
.battle-unit-copy{display:grid;gap:4px}

.battle-unit b{font:700 14px 'Space Grotesk',sans-serif}

.battle-tag{font:8px 'DM Mono',monospace;letter-spacing:.11em;color:#687457}

.battle-hp{font:9px 'DM Mono',monospace;display:grid;grid-template-columns:1fr auto;align-items:center;gap:7px}

.enc-message{min-height:34px;margin:13px 0 11px;color:#577066;font:10px 'DM Mono',monospace;line-height:1.5}

.battle-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}

.battle-move{border:1px solid #dce4d7;border-radius:9px;background:#edf2e8;padding:8px 5px;color:#3b5f51;cursor:pointer;font:10px 'Space Grotesk',sans-serif;font-weight:600}

